for did, (title, cat, pre, rows) in D.items():
    pairs, O, add = team_kit.deck(pre, "Grok Bot")
    for i,(ask,a,ad,b,bd) in enumerate(rows):
        add(cat, cat, O(f"{i}a", a, ad, "focused", V(a, ad, LAGOON)), O(f"{i}b", b, bd, "quick", V(b, bd, SAFFRON)), ask)
    assert len(pairs) == 20
    team_kit.publish(did, title, "Grok Bot", pairs, {"brands": ["How Grok Bot runs Max's agent team as CEO"], "submit_agent": "grok-bot", "submit_to": "Grok Bot",
        "section_counts": {cat: 20}, "deck_size": 20, "one_card_per_screen": True, "categories": [cat]}, seed=1014, n=20)
